// The planner's service worker, served from /sw.js. pwa/plugin.ts writes it into dist/ after each
// production build, with this build's file lists in place of the marker below. Hand-written
// rather than generated by Workbox: it does four things, and each one is visible here.
//
// 1. Install: fetch the app shell (index.html, the hashed bundles, the samples, engine.json) and
//    keep it only if every file matches the SHA-256 recorded at build time. A deploy in progress
//    can briefly serve a new sw.js beside an old index.html; that install fails and the browser
//    tries again later, instead of keeping a shell whose files do not belong together.
// 2. Runtime: the Pyodide files and the engine archive are versioned and immutable, so they are
//    kept the first time the planner uses the model (the page asks once the model is ready),
//    not at install: a visitor who only reads the Start screen is not sent 14 MB.
// 3. Serve: the shell and the runtime from the cache first, so the planner works offline.
//    engine.json is part of the shell, so the page and the engine it loads always move together.
//    Requests to other sites (map tiles) are never touched.
// 4. Update: a new version installs in the background and waits. The page offers a Reload, and
//    only the planner's click activates it, so a project is never reloaded out from under them.
//
// CloudFront serves large files Brotli-compressed with Content-Encoding: br, and compresses
// others on the fly. The browser hands this worker the decoded bytes, so a response is stored
// without its Content-Encoding and Content-Length, which describe the compressed bytes.

const MANIFEST = /* build: manifest */ null;

const SHELL_CACHE = `evsient-shell-${MANIFEST.version}`;
const RUNTIME_CACHE = 'evsient-runtime';
const scope = new URL(self.registration.scope);
const at = (path) => new URL(path, scope).pathname;
const SHELL = new Map(MANIFEST.shell.map((entry) => [at(entry.url), entry.sha256]));
const RUNTIME = new Set(MANIFEST.runtime.map(at));
const INDEX = at('index.html');

const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');

/** The response as the cache should hold it: decoded body, no transfer-encoding headers. */
function storable(response, body) {
  const headers = new Headers(response.headers);
  headers.delete('content-encoding');
  headers.delete('content-length');
  return new Response(body, { status: response.status, statusText: response.statusText, headers });
}

async function precache() {
  const cache = await caches.open(SHELL_CACHE);
  await Promise.all([...SHELL].map(async ([path, sha256]) => {
    // Hashed bundles may come from the HTTP cache; everything else is revalidated.
    const response = await fetch(path, { cache: path.startsWith(at('assets/')) ? 'default' : 'no-cache' });
    if (!response.ok) throw new Error(`${path}: HTTP ${response.status}`);
    const body = await response.arrayBuffer();
    if (hex(await crypto.subtle.digest('SHA-256', body)) !== sha256) {
      throw new Error(`${path} does not belong to this version; trying again later`);
    }
    await cache.put(path, storable(response, body));
  }));
}

/** Keep every runtime file this version uses. Most come straight from the HTTP cache. */
async function keepRuntime() {
  const cache = await caches.open(RUNTIME_CACHE);
  for (const path of RUNTIME) {
    if (await cache.match(path)) continue;
    const response = await fetch(path);
    if (response.ok) await cache.put(path, storable(response, await response.arrayBuffer()));
  }
}

self.addEventListener('install', (event) => {
  event.waitUntil(precache());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('evsient-shell-') && key !== SHELL_CACHE) await caches.delete(key);
    }
    // Runtime files another version used are dropped; their URLs stay on the server for rollback.
    const runtime = await caches.open(RUNTIME_CACHE);
    for (const request of await runtime.keys()) {
      if (!RUNTIME.has(new URL(request.url).pathname)) await runtime.delete(request);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  const type = event.data && event.data.type;
  if (type === 'skip-waiting') self.skipWaiting();
  if (type === 'keep-runtime') event.waitUntil(keepRuntime());
});

async function fromShell(path, request) {
  const hit = await caches.match(path, { cacheName: SHELL_CACHE });
  return hit || fetch(request);
}

async function fromRuntime(path, request) {
  const cache = await caches.open(RUNTIME_CACHE);
  const hit = await cache.match(path);
  if (hit) return hit;
  const response = await fetch(request);
  if (!response.ok) return response;
  const body = await response.arrayBuffer();
  await cache.put(path, storable(response, body.slice(0)));
  return storable(response, body);
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== scope.origin) return;
  const path = url.pathname;
  if (request.mode === 'navigate') {
    // One page: every step lives in the hash, so / and /index.html are the whole app.
    if (path === scope.pathname || path === INDEX) event.respondWith(fromShell(INDEX, request));
    return;
  }
  if (SHELL.has(path)) event.respondWith(fromShell(path, request));
  else if (RUNTIME.has(path)) event.respondWith(fromRuntime(path, request));
});
